module TimeHelper
  def browser_time_tag(timestamp, format: "relative", **attributes)
    data = attributes.delete(:data) || {}
    controllers = [ data[:controller], "time-display" ].compact.flat_map(&:split).uniq.join(" ")

    tag.time browser_time_value(timestamp),
      **attributes,
      datetime: browser_time_value(timestamp),
      data: data.merge(controller: controllers, time_display_format_value: format)
  end

  def browser_date_tag(date, **attributes)
    calendar_date = date.to_date.iso8601
    data = attributes.delete(:data) || {}
    controllers = [ data[:controller], "time-display" ].compact.flat_map(&:split).uniq.join(" ")

    tag.time calendar_date,
      **attributes,
      datetime: calendar_date,
      data: data.merge(controller: controllers, time_display_format_value: "calendar-date")
  end

  def browser_time_value(timestamp)
    timestamp.utc.iso8601(6)
  end
end
