const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const timeFormatter = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" })
const calendarDateFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const dateTimeFormatter = new Intl.DateTimeFormat("en-US", {
  month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatDateTime(value, format = "relative", now = new Date()) {
  const date = parseDate(value, format)
  if (!date || Number.isNaN(date.getTime())) return value

  switch (format) {
    case "relative":
      return formatRelativeDate(date, now)
    case "time":
      return timeFormatter.format(date)
    case "short-date":
      return formatShortDate(date, now)
    case "calendar-date":
      return calendarDateFormatter.format(date)
    case "date-time":
      return dateTimeFormatter.format(date)
    default:
      return value
  }
}

export function formatDateTimeTokens(value, format = "short-date") {
  return value.replace(/\{\{time:([^}]+)\}\}/g, (_token, timestamp) => formatDateTime(timestamp, format))
}

function formatRelativeDate(date, now) {
  const daysAgo = signedDifferenceInDays(date, now)

  if (daysAgo === 0) return timeFormatter.format(date)
  if (daysAgo === 1) return "yesterday"
  if (daysAgo === -1) return "tomorrow"

  if (Math.abs(daysAgo) < 7) {
    return daysAgo > 0 ? `${daysAgo} days ago` : `in ${Math.abs(daysAgo)} days`
  }

  return formatShortDate(date, now)
}

function formatShortDate(date, now) {
  const options = { month: "short", day: "numeric" }
  if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"
  return new Intl.DateTimeFormat("en-US", options).format(date)
}

function parseDate(value, format) {
  if (value instanceof Date) return value

  if (format === "calendar-date") {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
    if (!match) return new Date(value)

    const [, year, month, day] = match
    return new Date(Number(year), Number(month) - 1, Number(day))
  }

  return new Date(value)
}
