    case "date-time":
      return dateTimeFormatter.format(date)
    default:
      return value
  }
}

export function formatDateTimeTokens(value, format = "short-date") {
  if (!value) return value
  return value.replace(/\{\{time:([^}]+)\}\}/g, (_token, timestamp) => formatDateTime(timestamp, format))
}

function formatRelativeDate(date, now) {
  const daysAgo = signedDifferenceInDays(date, now)

  if (daysAgo === 0) return timeFormatter.format(date)
  if (daysAgo === 1) return "yesterday"
  if (daysAgo === -1) return "tomorrow"

  if (Math.abs(daysAgo) < 7) {
    return daysAgo > 0 ? `${daysAgo} days ago` : `in ${Math.abs(daysAgo)} days`
  }

  return formatShortDate(date, now)
}

function formatShortDate(date, now) {
  const formatter = date.getFullYear() === now.getFullYear() ? shortDateFormatter : shortDateWithYearFormatter
  return formatter.format(date)
}

function parseDate(value, format) {
  if (value instanceof Date) return value

  if (format === "calendar-date") {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)
    if (!match) return new Date(value)

    const [, year, month, day] = match
    return new Date(Number(year), Number(month) - 1, Number(day))
  }

  return new Date(value)
}
